// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {W_WALLET, Log} from "../src/W_WALLET.sol";

contract InvMutTest is Test {
    W_WALLET c;

    function setUp() public { c = new W_WALLET(address(new Log())); }

    function testFuzz_property(uint256 warpTo, uint256 unlock, address actor) public {
        vm.assume(actor != address(0));
        warpTo = bound(warpTo, 1, type(uint64).max);
        unlock = bound(unlock, 0, type(uint64).max);
        vm.warp(warpTo);
        vm.deal(actor, 1 wei);
        vm.prank(actor);
        c.Put{value: 1 wei}(unlock);
        (uint256 storedUnlock, ) = c.Acc(actor);
        assertTrue(storedUnlock >= block.timestamp);
    }
}
